nginx_config:
daemon off;
master_process on;
worker_processes 2;
pid /tmp/aegisx-bench-bk9g8r2r/nginx.pid;
error_log /tmp/aegisx-bench-bk9g8r2r/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-bench-bk9g8r2r/body;
    proxy_temp_path /tmp/aegisx-bench-bk9g8r2r/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;
    proxy_cache_path /tmp/aegisx-bench-bk9g8r2r/cache levels=1 keys_zone=zone:16m max_size=128m inactive=60s use_temp_path=off;
    upstream origin { server 10.42.1.170:3800; keepalive 256; }
    server {
        listen 10.42.1.79:35087   reuseport;
        location / {
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host 10.42.1.170:3800;
            proxy_cache zone;
            proxy_cache_valid 200 60s;
            proxy_ignore_headers Cache-Control Expires Set-Cookie;
            proxy_pass http://origin;
        }
    }
}
